ALTER TABLE public.provider_customer_pricing_versions ADD COLUMN IF NOT EXISTS payer_id uuid REFERENCES public.payers(id), ADD COLUMN IF NOT EXISTS effective_end date, ADD COLUMN IF NOT EXISTS agreement_active boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS agreement_label text, ADD COLUMN IF NOT EXISTS agreement_notes text;
CREATE POLICY payer_manager_read ON public.provider_customer_pricing_versions FOR SELECT TO authenticated USING(payer_id IS NOT NULL AND public.business_record_access(workspace_id,'payers',payer_id,'manage'));
CREATE OR REPLACE FUNCTION public.save_payer_rate_version(_workspace uuid,_payer uuid,_rates jsonb,_start date,_end date,_active boolean,_label text,_notes text,_expected integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer;result uuid;s text;v jsonb;k text; BEGIN
IF NOT public.can_manage_account_connections(_workspace) OR NOT public.business_record_access(_workspace,'payers',_payer,'manage') OR NOT EXISTS(SELECT 1 FROM public.payers WHERE id=_payer AND workspace_id=_workspace AND active) THEN RAISE EXCEPTION 'Authorized workspace payer required'; END IF;
IF _end<_start OR length(_label)>160 OR length(_notes)>1000 OR _start IS NULL THEN RAISE EXCEPTION 'Invalid agreement dates or details'; END IF;
PERFORM 1 FROM public.workspaces WHERE id=_workspace FOR UPDATE;
SELECT coalesce(max(version),0) INTO n FROM public.provider_customer_pricing_versions WHERE workspace_id=_workspace;
IF n<>_expected THEN RAISE EXCEPTION 'Rates changed; reload before saving';END IF;
IF jsonb_typeof(_rates)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(_rates))<>4 THEN RAISE EXCEPTION 'Four service rates required';END IF;
FOREACH s IN ARRAY ARRAY['ambulatory','wheelchair','stretcher','medical_delivery'] LOOP
IF jsonb_typeof(_rates->s)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(_rates->s))<>19 THEN RAISE EXCEPTION 'Invalid service rate';END IF;
FOR k,v IN SELECT key,value FROM jsonb_each(_rates->s) LOOP IF k IN ('wait_unit','round_trip','after_hours_start','after_hours_end','holidays') THEN CONTINUE;END IF;IF jsonb_typeof(v)<>'number' OR v::text::numeric<0 OR (k<>'included_miles' AND (v::text::numeric<>trunc(v::text::numeric) OR v::text::numeric>9007199254740991)) THEN RAISE EXCEPTION 'Invalid rate component';END IF;END LOOP;
IF _rates->s->>'wait_unit' NOT IN ('minute','half_hour','hour') OR _rates->s->>'round_trip' NOT IN ('per_leg','single_pickup') OR _rates->s->>'after_hours_start'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR _rates->s->>'after_hours_end'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR jsonb_typeof(_rates->s->'holidays')<>'array' THEN RAISE EXCEPTION 'Invalid behavior';END IF;END LOOP;
INSERT INTO public.provider_customer_pricing_versions(workspace_id,payer_id,version,effective_at,effective_end,agreement_active,agreement_label,agreement_notes,created_by,person_mfn_id,workspace_mfn_id,rates) VALUES(_workspace,_payer,n+1,_start::timestamp AT TIME ZONE 'America/New_York',_end,_active,_label,_notes,auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),(SELECT mfn_id FROM public.workspaces WHERE id=_workspace),_rates) RETURNING id INTO result;RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_payer_rate_version(uuid,uuid,jsonb,date,date,boolean,text,text,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_payer_rate_version(uuid,uuid,jsonb,date,date,boolean,text,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.stamp_relationship_audit_ids() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.person_mfn_id:=coalesce(NEW.person_mfn_id,(SELECT mfn_id FROM public.user_profiles WHERE user_id=NEW.actor_id));NEW.workspace_mfn_id:=coalesce(NEW.workspace_mfn_id,(SELECT mfn_id FROM public.workspaces WHERE id=NEW.workspace_id));RETURN NEW;END $$;
CREATE TRIGGER stamp_relationship_audit_ids BEFORE INSERT ON public.account_relationship_events FOR EACH ROW EXECUTE FUNCTION public.stamp_relationship_audit_ids();